<?php
// Shared in-page confirmation modal for player-facing pages.
// Any <form data-confirm="Message?"> is intercepted and confirmed through this
// dialog instead of the browser's native confirm(). Include once per page.
?>
<style>
.toinky-confirm-overlay{position:fixed;inset:0;background:rgba(28,36,43,.55);display:flex;align-items:center;justify-content:center;z-index:1200;padding:18px}.toinky-confirm-overlay[hidden]{display:none}.toinky-confirm-dialog{background:#F4EEE2;color:#1C242B;border-radius:14px;padding:22px;max-width:420px;width:100%;box-shadow:0 18px 50px rgba(0,0,0,.35);font-family:Inter,system-ui,sans-serif}.toinky-confirm-dialog p{margin:0 0 18px;font-size:15px;line-height:1.5}.toinky-confirm-actions{display:flex;gap:10px;justify-content:flex-end}.toinky-confirm-actions .btn{border:0;border-radius:8px;background:#B58E46;color:#1C242B;padding:10px 14px;font-weight:800;cursor:pointer;font:inherit}.toinky-confirm-actions .btn.alt{background:#fff;color:#6B2938;border:1px solid #6B2938}.toinky-confirm-actions .btn.danger{background:#6B2938;color:#fff}
</style>
<div class="toinky-confirm-overlay" id="toinky-confirm" hidden><div class="toinky-confirm-dialog" role="alertdialog" aria-modal="true" aria-labelledby="toinky-confirm-message"><p id="toinky-confirm-message"></p><div class="toinky-confirm-actions"><button type="button" class="btn alt" data-toinky-confirm-cancel>Cancel</button><button type="button" class="btn danger" data-toinky-confirm-ok>Confirm</button></div></div></div>
<script>
const toinkyConfirm=message=>new Promise(resolve=>{const overlay=document.getElementById('toinky-confirm');if(!overlay){resolve(window.confirm(message));return;}if(!overlay.hidden){resolve(false);return;}const text=overlay.querySelector('#toinky-confirm-message'),okButton=overlay.querySelector('[data-toinky-confirm-ok]'),cancelButton=overlay.querySelector('[data-toinky-confirm-cancel]'),previous=document.activeElement;text.textContent=message;overlay.hidden=false;const close=value=>{overlay.hidden=true;okButton.removeEventListener('click',onOk);cancelButton.removeEventListener('click',onCancel);overlay.removeEventListener('click',onBackdrop);document.removeEventListener('keydown',onKey);if(previous&&previous.focus)previous.focus();resolve(value);};const onOk=()=>close(true),onCancel=()=>close(false),onBackdrop=event=>{if(event.target===overlay)close(false);},onKey=event=>{if(event.key==='Escape')close(false);};okButton.addEventListener('click',onOk);cancelButton.addEventListener('click',onCancel);overlay.addEventListener('click',onBackdrop);document.addEventListener('keydown',onKey);cancelButton.focus();});
document.addEventListener('submit',event=>{const form=event.target;if(!(form instanceof HTMLFormElement)||!form.dataset.confirm||form.dataset.toinkyConfirmed==='true')return;event.preventDefault();event.stopPropagation();event.stopImmediatePropagation();const submitter=event.submitter||null;toinkyConfirm(form.dataset.confirm).then(ok=>{if(!ok)return;form.dataset.toinkyConfirmed='true';if(submitter)form.requestSubmit(submitter);else form.requestSubmit();});},true);
</script>
